//! Ephemeral local authority. These IDs are never company/account credentials
//! and are generated by Rust rather than accepted over frontend IPC.
use crate::HostError;
use serde::{Deserialize, Serialize};

const VERSION: u32 = 1;
const FEATURES: [&str; 4] = [
    "session-authority-v1",
    "native-action-allowlist-v1",
    "read-grants-v1",
    "guarded-file-mutations-v1",
];

#[derive(Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Authority {
    pub(crate) principal_id: String,
    pub(crate) workspace_id: String,
    pub(crate) generation: String,
    pub(crate) policy_revision: u64,
    pub(crate) grant_revision: u64,
}

pub(crate) fn random_id() -> Result<String, HostError> {
    let mut bytes = [0u8; 16];
    getrandom::getrandom(&mut bytes).map_err(|_| HostError::RandomUnavailable)?;
    Ok(bytes.iter().map(|b| format!("{b:02x}")).collect())
}

impl Authority {
    pub(crate) fn with_grant_revision(&self, revision: u64) -> Self {
        let mut authority = self.clone();
        authority.grant_revision = revision;
        authority
    }
    pub(crate) fn generate() -> Result<Self, HostError> {
        Ok(Self {
            principal_id: format!("local-user-{}", random_id()?),
            workspace_id: format!("local-workspace-{}", random_id()?),
            generation: random_id()?,
            policy_revision: 1,
            grant_revision: 0,
        })
    }
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Protocol {
    protocol_version: u32,
    mode: String,
    features: Vec<String>,
}
impl Protocol {
    pub(crate) fn compatible(&self) -> bool {
        self.protocol_version == VERSION
            && self.mode == "local"
            && self.features.iter().map(String::as_str).eq(FEATURES)
    }
}

#[derive(Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub(crate) struct Binding {
    protocol_version: u32,
    authority: Authority,
}
impl Binding {
    pub(crate) fn new(authority: Authority) -> Self {
        Self {
            protocol_version: VERSION,
            authority,
        }
    }
}
